unsigned char *download_bof(const bsb_config_t *cfg, const char *url, size_t *out_size) {
    http_response_t resp = https_request(cfg, url, "GET", NULL);
    if (!resp.data || resp.len == 0) {
        *out_size = 0;
        free(resp.data);
        return NULL;
    }
    *out_size = resp.len;
    return (unsigned char *)resp.data;
}

